// Arma el resumen diario para Telegram (parse_mode HTML): lo que subió de
// prioridad hoy y lo que sigue en CRITICA sin resolver. Los títulos los
// escribe quien crea el ticket, así que pasan por esc().
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json || {};
const escaladas = Array.isArray(r.escaladas) ? r.escaladas : [];
const criticos = Array.isArray(r.criticos) ? r.criticos : [];
const lineas = ['🎫 <b>Tickets</b>', 'Abiertos: <b>' + Number(r.abiertos || 0) + '</b>'];
if (escaladas.length) {
  lineas.push('', '⬆️ <b>Subieron de prioridad (' + escaladas.length + ')</b>');
  for (const t of escaladas.slice(0, 10)) lineas.push('• ' + esc(t.titulo) + ' → <b>' + esc(t.prioridad) + '</b>');
  if (escaladas.length > 10) lineas.push('… y ' + (escaladas.length - 10) + ' más.');
}
if (criticos.length) {
  lineas.push('', '🔥 <b>En CRITICA sin resolver</b>');
  for (const t of criticos.slice(0, 10)) lineas.push('• ' + esc(t.titulo) + ' (' + Number(t.dias) + 'd quieto)');
}
if (!escaladas.length && !criticos.length) lineas.push('', '✅ Nada escaló hoy, el tablero está al día.');
return [{ json: { texto: lineas.join('\n') } }];
